import { brandOf, type Brand } from "../lib/model-brand.ts";

/**
 * The mark of whoever made the model, beside its name.
 *
 * A model list is a column of near-identical strings — `deepseek-v4-flash`, `gpt-5.2`,
 * `claude-opus-5` — and reading it means reading every line. A brand mark is found before any of
 * them is read, which is the point: you are almost always looking for a house, not a version.
 *
 * Every mark below is the official vector, taken from the vendor's own site or CDN — the address
 * is on the line above each one. None of it is drawn here. An approximation of somebody's logo is
 * worse than no logo: it is recognisably wrong, and it is their trademark being got wrong.
 *
 * Colour comes from the brand where the brand has one. Where the official mark is monochrome
 * (OpenAI, xAI) it takes full ink instead — their owners draw them black on white and white on
 * black, and `currentColor` alone would have inherited whatever muted grey the row is set in,
 * leaving those two visibly weaker than the coloured marks beside them in the same list.
 *
 * A model whose house is not in the table gets the neutral box. Adding one means finding its
 * official vector and pasting the path, not tracing it.
 */

/** Path data as the vendor published it, keyed by the brand `modelBrand.ts` resolves to. */
