/**
 * `model` is matched on id and display name together — see `modelBrand.ts` for why both.
 *
 * `size` is in px and drives width and height alike; every mark is square, whatever its own
 * viewBox says. Marked `aria-hidden` throughout: the name it sits beside is already the label,
 * and a screen reader announcing "DeepSeek DeepSeek V4 Flash" is worse than silence.
 */
export function ModelIcon({
	model,
	name,
	size = 13,
	className = "",
}: {
	model: string | null | undefined;
	/** The display name, when it is not the same string as the id. */
	name?: string | null;
	size?: number;
	className?: string;
}) {
	// Stable per mounted icon, so two Geminis on one screen do not share one gradient id.
	const gradientId = useId();
	const brand = brandOf(model, name);
	const mark = brand ? MARKS[brand] : null;

	if (!mark)
		return <Box size={size} strokeWidth={1.7} className={`shrink-0 text-ink-faint ${className}`} aria-hidden />;

	return (
		<svg
			width={size}
			height={size}
			viewBox={mark.box}
			fill="none"
			xmlns="http://www.w3.org/2000/svg"
			// Full ink for the monochrome marks; the coloured ones carry their own and inherit nothing.
			className={`shrink-0 ${mark.mono ? "text-ink" : ""} ${className}`}
			aria-hidden
		>
			{mark.draw(gradientId)}
		</svg>
	);
}
